function validate([words]) {
  if (!Array.isArray(words) || words.length < 2 || words.length > 1000) return 'words needs 2 to 1000 words.';
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 1000) return 'Each word has 1 to 1000 letters.';
    if (!/^[a-z]+$/.test(word)) return 'Words use only lowercase letters.';
  }
  return null;
}

