function maxProduct(words) {
  // Compare every ordered pair letter by letter with a set; no bit tricks.
  let best = 0;
  for (let i = 0; i < words.length; i++) {
    const letters = new Set(words[i]);
    for (let j = 0; j < words.length; j++) {
      if (i === j) continue;
      let shared = false;
      for (const c of words[j]) if (letters.has(c)) { shared = true; break; }
      if (!shared && words[i].length * words[j].length > best) best = words[i].length * words[j].length;
    }
  }
  return best;
}

