function generate(rand, size) {
  const pick = m => Math.floor(rand() * m);
  const all = 'abcdefghijklmnopqrstuvwxyz';
  // A smaller alphabet makes shared letters, and so a 0 answer, more likely.
  const alphabet = all.slice(0, size === 'large' ? 10 + pick(17) : 3 + pick(8));
  const n = size === 'large' ? 1000 : 2 + pick(7);
  const maxLength = size === 'large' ? 12 : 1 + pick(5);
  const words = [];
  for (let i = 0; i < n; i++) {
    const length = 1 + pick(maxLength);
    let word = '';
    for (let k = 0; k < length; k++) word += alphabet[pick(alphabet.length)];
    words.push(word);
  }
  return [words];
}
